/* v9: pre-recorded neural audio (Microsoft es-MX voices, generated by tools/build_audio.py into audio/).
   Pure helpers (norm / lookup / castFor / files) are unit-tested. The player keeps ONE HTMLAudioElement that is unlocked
   on the first tap (iOS only lets a page start audio from a user gesture, and an element unlocked once stays playable),
   and plays blob: URLs because iOS Safari can't play media straight out of a service-worker cache (it wants range replies).
   Anything missing from the manifest, or any play() failure, returns false/rejects so the app falls back to Web Speech. */
(function (root) {
  const AUDIO_CACHE = 'espanol-audio'; // content-hashed file names, so this cache survives app updates
  const norm = t => String(t || '').normalize('NFC').replace(/\s+/g, ' ').trim().toLowerCase();
  function lookup(man, text, voice) {
    if (!man || !man.files) return null;
    const m = man.files[voice || man.main], h = m && m[norm(text)];
    return h ? 'audio/' + h + '.mp3' : null;
  }
  // story speaker → recorded voice id ('' = narrator). Unknown story/speaker → main voice.
  function castFor(man, unitId, speaker) { const c = man && man.cast && man.cast[unitId]; return (c && (c[speaker || ''] || c[''])) || (man && man.main) || null; }
  function files(man) { const out = new Set(); if (man && man.files) Object.values(man.files).forEach(m => Object.values(m).forEach(h => out.add('audio/' + h + '.mp3'))); return [...out]; }
  const Rec = { AUDIO_CACHE, norm, lookup, castFor, files, man: null };
  if (typeof module !== 'undefined') { module.exports = Rec; return; }

  const SILENT = 'data:audio/mpeg;base64,';
  let el = null, unlocked = false, seq = 0;
  const blobs = new Map(); // path → blob URL (small LRU)
  const media = () => el || (el = new Audio());
  Rec.unlock = () => {
    if (unlocked) return; unlocked = true;
    try { const a = media(); a.muted = true; a.src = SILENT; const p = a.play(); if (p && p.then) p.then(() => { a.pause(); a.muted = false; }, () => { a.muted = false; unlocked = false; }); else a.muted = false; } catch (e) { unlocked = false; }
  };
  Rec.load = () => fetch('audio/manifest.json').then(r => r.ok ? r.json() : null).then(m => { if (m && m.files) Rec.man = m; return Rec.man; }).catch(() => null);
  async function blobUrl(path) {
    if (blobs.has(path)) { const u = blobs.get(path); blobs.delete(path); blobs.set(path, u); return u; }
    const r = await fetch(path); if (!r.ok) throw new Error(path + ' ' + r.status);
    const u = URL.createObjectURL(await r.blob()); blobs.set(path, u);
    if (blobs.size > 80) { const [k, old] = blobs.entries().next().value; blobs.delete(k); URL.revokeObjectURL(old); }
    return u;
  }
  Rec.stop = () => { seq++; if (el) try { el.pause(); } catch (e) { /* ignore */ } };
  // resolves true when playback started; rejects on a missing file / blocked play so the caller can fall back
  Rec.play = (path, rate) => {
    const my = ++seq; if (el) try { el.pause(); } catch (e) { /* ignore */ }
    if (root.__audioLog) root.__audioLog.push({ src: path, rate });
    return blobUrl(path).then(u => {
      if (my !== seq) return true; // a newer sound replaced this one
      const a = media(); a.muted = false; a.src = u; a.defaultPlaybackRate = a.playbackRate = rate || 1;
      if ('preservesPitch' in a) a.preservesPitch = true; else if ('webkitPreservesPitch' in a) a.webkitPreservesPitch = true;
      const p = a.play(); return p && p.then ? p.then(() => { a.playbackRate = rate || 1; return true; }) : true;
    });
  };
  Rec.playing = () => !!(el && !el.paused && !el.ended);
  // fill the offline audio cache with the given files (only missing ones), a few at a time
  Rec.prefetch = async (paths, onProgress) => {
    if (!('caches' in root) || !paths || !paths.length) return 0;
    const c = await caches.open(AUDIO_CACHE); const have = new Set((await c.keys()).map(r => new URL(r.url).pathname.replace(/^.*\/audio\//, 'audio/')));
    const todo = paths.filter(p => !have.has(p)); let done = 0;
    const worker = async () => { while (todo.length) { const p = todo.shift(); try { const r = await fetch(p); if (r.ok) await c.put(p, r); } catch (e) { /* offline: try next time */ } done++; if (onProgress) onProgress(done); } };
    await Promise.all([1, 2, 3, 4, 5, 6].map(worker)); return done;
  };
  Rec.cachedCount = async () => { if (!('caches' in root)) return 0; const c = await caches.open(AUDIO_CACHE); return (await c.keys()).length; };
  // drop cached clips that the current manifest no longer uses (text changed → new hash)
  Rec.prune = async () => {
    if (!('caches' in root) || !Rec.man) return 0; const keep = new Set(files(Rec.man)); const c = await caches.open(AUDIO_CACHE); let n = 0;
    for (const r of await c.keys()) { const p = new URL(r.url).pathname.replace(/^.*\/audio\//, 'audio/'); if (!keep.has(p)) { await c.delete(r); n++; } }
    return n;
  };
  root.Rec = Rec;
})(typeof window !== 'undefined' ? window : globalThis);
